class Solution {
public:
    vector<int> countServers(int n, vector<vector<int>>& logs, int x, vector<int>& queries) {
        int q = queries.size();
        vector<pair<int, int>> sorted_queries(q);
        for (int i = 0; i < q; ++i) {
            sorted_queries[i] = {queries[i], i};
        }

        sort(sorted_queries.begin(), sorted_queries.end());
        sort(logs.begin(), logs.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });

        vector<int> freq(n + 1, 0);
        int active = 0;
        int left = 0;
        int right = 0;
        vector<int> ans(q);

        for (int i = 0; i < q; ++i) {
            int q_time = sorted_queries[i].first;
            int q_idx = sorted_queries[i].second;
            int start_time = q_time - x;

            while (right < logs.size() && logs[right][1] <= q_time) {
                int server = logs[right][0];
                if (freq[server] == 0) {
                    active++;
                }
                freq[server]++;
                right++;
            }

            while (left < right && logs[left][1] < start_time) {
                int server = logs[left][0];
                freq[server]--;
                if (freq[server] == 0) {
                    active--;
                }
                left++;
            }

            ans[q_idx] = n - active;
        }

        return ans;
    }
};
